import sqlite3
from typing import Dict, List, Tuple, Any

import numpy as np

from pymilvus import connections, Collection


# ----------------------------
# Fixed configuration (as required)
# ----------------------------
sqlite_paths = {
    "business": "D:/Yelp-JSON/db/sqlite3/business.db",
    "checkin": "D:/Yelp-JSON/db/sqlite3/checkin.db",
    "photo": "D:/Yelp-JSON/db/sqlite3/photo.db",
    "review": "D:/Yelp-JSON/db/sqlite3/review.db",
    "tip": "D:/Yelp-JSON/db/sqlite3/tip.db",
    "user": "D:/Yelp-JSON/db/sqlite3/user.db"
}

milvus_config = {
    'milvus_collections': {
        'reviews': 'reviews',
        'photos': 'photo_vector',
        'tips': 'milvus_tip'
    },
    'milvus_host': 'localhost',
    'milvus_port': '19530'
}

neo4j_config = {
    'neo4j_uri': 'bolt://localhost:7687',
    'neo4j_auth': ('neo4j', 'password')
}


# ----------------------------
# Utilities
# ----------------------------
def dict_factory(cursor, row):
    d = {}
    for idx, col in enumerate(cursor.description):
        d[col[0]] = row[idx]
    return d


def connect_sqlite(path: str) -> sqlite3.Connection:
    conn = sqlite3.connect(path)
    conn.row_factory = dict_factory
    return conn


def milvus_connect():
    connections.connect(
        alias="default",
        host=milvus_config['milvus_host'],
        port=milvus_config['milvus_port']
    )


def get_vector_field_name(col: Collection) -> str:
    # Heuristic: pick the first FLOAT_VECTOR field
    for f in col.schema.fields:
        # pymilvus uses DataType enum; compare by name to avoid version mismatch
        if str(f.dtype).endswith("FLOAT_VECTOR") or "FLOAT_VECTOR" in str(f.dtype):
            return f.name
    # common fallback
    return "embedding"


def get_primary_field_name(col: Collection) -> str:
    for f in col.schema.fields:
        if getattr(f, "is_primary", False):
            return f.name
    # common fallback
    return "id"


def guess_text_id_field(col: Collection) -> str:
    # We want something like review_id or tip_id if present.
    candidates = ["review_id", "tip_id", "id", "pk"]
    field_names = [f.name for f in col.schema.fields]
    for c in candidates:
        if c in field_names:
            return c
    # fallback to primary key
    return get_primary_field_name(col)


def embed_query_simple(text: str, dim: int) -> List[float]:
    """Placeholder embedder.

    IMPORTANT:
    - In a real system, you should use the same embedding model used to build Milvus vectors.
    - Here we provide a deterministic pseudo-embedding so the code is runnable, but relevance will be poor.

    Replace this function with e.g. OpenAI, sentence-transformers, etc.
    """
    rng = np.random.default_rng(abs(hash(text)) % (2**32))
    v = rng.normal(size=dim).astype(np.float32)
    v /= (np.linalg.norm(v) + 1e-9)
    return v.tolist()


def milvus_semantic_search(collection_name: str, query_text: str, limit: int = 200) -> List[Dict[str, Any]]:
    col = Collection(collection_name)
    col.load()

    vec_field = get_vector_field_name(col)
    pk_field = get_primary_field_name(col)
    id_field = guess_text_id_field(col)

    # Determine vector dimension
    dim = None
    for f in col.schema.fields:
        if f.name == vec_field:
            dim = getattr(f, "params", {}).get("dim") or getattr(f, "dim", None)
            break
    if dim is None:
        # conservative fallback
        dim = 1536

    query_vec = embed_query_simple(query_text, int(dim))

    # Try to return useful fields if they exist
    output_fields = list({pk_field, id_field, "business_id", "review_id", "tip_id"})

    search_params = {"metric_type": "IP", "params": {"nprobe": 16}}
    try:
        res = col.search(
            data=[query_vec],
            anns_field=vec_field,
            param=search_params,
            limit=limit,
            output_fields=output_fields
        )
    except Exception:
        # fallback metric
        search_params = {"metric_type": "L2", "params": {"nprobe": 16}}
        res = col.search(
            data=[query_vec],
            anns_field=vec_field,
            param=search_params,
            limit=limit,
            output_fields=output_fields
        )

    hits = []
    for hit in res[0]:
        row = {"score": float(hit.score)}
        try:
            ent = hit.entity
            # entity.get(...) works in recent pymilvus
            for f in output_fields:
                try:
                    row[f] = ent.get(f)
                except Exception:
                    pass
        except Exception:
            pass
        hits.append(row)

    return hits


def fetch_business_candidates(conn_business: sqlite3.Connection, city: str = "Clearwater") -> List[Dict[str, Any]]:
    keywords = ["%Gym%", "%Fitness%", "%Health%", "%Trainer%", "%Personal Trainer%"]
    where_like = " OR ".join(["categories LIKE ?" for _ in keywords])
    sql = f"""
    SELECT business_id, name, address, city, state, postal_code, stars, review_count, categories
    FROM business
    WHERE city = ?
      AND ({where_like})
    """
    params = [city] + keywords
    return conn_business.execute(sql, params).fetchall()


def chunked(lst: List[Any], n: int = 900) -> List[List[Any]]:
    return [lst[i:i+n] for i in range(0, len(lst), n)]


def fetch_reviews_by_ids(conn_review: sqlite3.Connection, review_ids: List[str]) -> List[Dict[str, Any]]:
    if not review_ids:
        return []
    out = []
    for ch in chunked(review_ids, 900):
        placeholders = ",".join(["?"] * len(ch))
        sql = f"""
        SELECT review_id, business_id, stars, date, text
        FROM review
        WHERE review_id IN ({placeholders})
        """
        out.extend(conn_review.execute(sql, ch).fetchall())
    return out


def fetch_tips_by_ids(conn_tip: sqlite3.Connection, tip_ids: List[str]) -> List[Dict[str, Any]]:
    if not tip_ids:
        return []
    out = []
    for ch in chunked(tip_ids, 900):
        placeholders = ",".join(["?"] * len(ch))
        sql = f"""
        SELECT tip_id, business_id, date, text
        FROM tip
        WHERE tip_id IN ({placeholders})
        """
        out.extend(conn_tip.execute(sql, ch).fetchall())
    return out


def main():
    # 1) Connect SQLite
    conn_business = connect_sqlite(sqlite_paths["business"])
    conn_review = connect_sqlite(sqlite_paths["review"])
    conn_tip = connect_sqlite(sqlite_paths["tip"])

    # 2) Candidate gyms in Clearwater
    candidates = fetch_business_candidates(conn_business, city="Clearwater")
    if not candidates:
        print("No gym-like businesses found in Clearwater with the current category filter.")
        return

    candidate_ids = {b["business_id"] for b in candidates}

    # 3) Milvus semantic search over reviews and tips
    milvus_connect()

    review_query = "good personal trainers and modern equipment"
    tip_query = "great trainers, personal training, new equipment, modern machines, clean equipment"

    review_hits = milvus_semantic_search(milvus_config['milvus_collections']['reviews'], review_query, limit=250)
    tip_hits = milvus_semantic_search(milvus_config['milvus_collections']['tips'], tip_query, limit=250)

    # 4) Map hits -> IDs we can backfill from SQLite
    # Prefer explicit review_id/tip_id; fall back to primary key if it is actually the id used in SQLite.
    review_ids = []
    for h in review_hits:
        rid = h.get("review_id") or h.get("id") or h.get("pk")
        if rid is not None:
            review_ids.append(str(rid))

    tip_ids = []
    for h in tip_hits:
        tid = h.get("tip_id") or h.get("id") or h.get("pk")
        if tid is not None:
            tip_ids.append(str(tid))

    reviews = fetch_reviews_by_ids(conn_review, review_ids)
    tips = fetch_tips_by_ids(conn_tip, tip_ids)

    # 5) Aggregate evidence at business level, restricted to Clearwater candidates
    by_business: Dict[str, Dict[str, Any]] = {}
    for b in candidates:
        by_business[b["business_id"]] = {
            "business": b,
            "review_hit_count": 0,
            "tip_hit_count": 0,
            "review_evidence": [],
            "tip_evidence": []
        }

    # keep a few evidence snippets per business
    def add_review_evidence(row):
        bid = row["business_id"]
        if bid in by_business:
            by_business[bid]["review_hit_count"] += 1
            if len(by_business[bid]["review_evidence"]) < 3:
                txt = (row.get("text") or "").replace("\n", " ")
                by_business[bid]["review_evidence"].append(txt[:280])

    def add_tip_evidence(row):
        bid = row["business_id"]
        if bid in by_business:
            by_business[bid]["tip_hit_count"] += 1
            if len(by_business[bid]["tip_evidence"]) < 3:
                txt = (row.get("text") or "").replace("\n", " ")
                by_business[bid]["tip_evidence"].append(txt[:280])

    for r in reviews:
        # filter to Clearwater gym candidates only
        if r.get("business_id") in candidate_ids:
            add_review_evidence(r)

    for t in tips:
        if t.get("business_id") in candidate_ids:
            add_tip_evidence(t)

    # 6) Rank
    ranked = []
    for bid, obj in by_business.items():
        b = obj["business"]
        stars = float(b.get("stars") or 0.0)
        review_count = int(b.get("review_count") or 0)
        rh = obj["review_hit_count"]
        th = obj["tip_hit_count"]

        # Simple scoring: semantic evidence + base stars + (log-scaled popularity)
        score = (rh * 2.0) + (th * 1.0) + (stars * 1.5) + (np.log1p(review_count) * 0.3)

        ranked.append({
            "business_id": bid,
            "name": b.get("name"),
            "address": ", ".join([str(x) for x in [b.get("address"), b.get("city"), b.get("state"), b.get("postal_code")] if x]),
            "stars": stars,
            "review_count": review_count,
            "categories": b.get("categories"),
            "review_hit_count": rh,
            "tip_hit_count": th,
            "score": float(score),
            "review_evidence": obj["review_evidence"],
            "tip_evidence": obj["tip_evidence"]
        })

    ranked.sort(key=lambda x: x["score"], reverse=True)

    # 7) Output top results
    top_k = 10
    print(f"Top {top_k} Clearwater gyms likely to have good personal trainers and modern equipment (semantic evidence from reviews/tips):\n")
    for i, r in enumerate(ranked[:top_k], start=1):
        print(f"{i}. {r['name']}  | stars={r['stars']}  reviews={r['review_count']}  | review_hits={r['review_hit_count']} tip_hits={r['tip_hit_count']}  | score={r['score']:.3f}")
        print(f"   Address: {r['address']}")
        if r.get("review_evidence"):
            print("   Review evidence:")
            for s in r["review_evidence"]:
                print(f"     - {s}")
        if r.get("tip_evidence"):
            print("   Tip evidence:")
            for s in r["tip_evidence"]:
                print(f"     - {s}")
        print("")


if __name__ == "__main__":
    try:
        main()
    except Exception as e:
        # Basic error handling; for debugging you may want traceback.print_exc()
        print("Error:", repr(e))

